import sys
from collections import deque

data = sys.stdin.read().split()
t = int(data[0])
out = []
for k in range(1, t + 1):
    s = data[k]
    seen = {s}
    dq = deque([s])
    while dq:
        cur = dq.popleft()
        for i in range(len(cur) - 1):
            if (int(cur[i]) + int(cur[i + 1])) % 2 == 1:
                nxt = cur[:i] + cur[i + 1] + cur[i] + cur[i + 2:]
                if nxt not in seen:
                    seen.add(nxt)
                    dq.append(nxt)
    out.append(min(seen))
print('\n'.join(out))

